import{E as e,d as t,l as n}from"./runtime-core.esm-bundler-tCF-J6l5.js";import{t as r}from"./app-DCZUiBeJ.js";var i=JSON.parse(`{"path":"/%E8%AF%AD%E8%A8%80/%E8%8B%B1%E8%AF%AD/Friends%E8%80%81%E5%8F%8B%E8%AE%B0/S05/S05E21.html","title":"S05E21 The One with the Ball","lang":"zh-CN","frontmatter":{"title":"S05E21 The One with the Ball","pageClass":"friends-page","category":["英语"],"tag":["Friends老友记"],"order":118},"git":{"createdTime":1780654155000,"updatedTime":1780664804000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":3}]},"readingTime":{"minutes":36.3,"words":10890},"filePathRelative":"语言/英语/Friends老友记/S05/S05E21.md"}`),a={name:`S05E21.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="the-one-with-the-ball" tabindex="-1"><a class="header-anchor" href="#the-one-with-the-ball"><span>The One with the Ball</span></a></h1><blockquote><p><em>拿球的那个</em></p></blockquote><p>The One With The Ball</p><blockquote><p>拿球的那个</p></blockquote><p><strong>Teleplay by:</strong> Greg Malins</p><blockquote><p>格雷格·马林斯</p></blockquote><p><strong>Story by:</strong> Scott Silveri</p><blockquote><p>斯科特·西尔维尼</p></blockquote><p><strong>Transcribed by: Eric Aasen</strong></p><blockquote><p>转录人：埃里克·艾森</p></blockquote><hr><p>🎬 <em>Central Perk, Gary, Phoebe, Monica, and Chandler are there.</em></p><blockquote><p>🎬 <em>中央公园、加里、菲比、莫妮卡和钱德勒在那里。</em></p></blockquote><p><strong>Gary:</strong> (To Phoebe) Would you like some more coffee, baby-doll?</p><blockquote><p>（对菲比）你想再来点咖啡吗，娃娃？</p></blockquote><p><strong>Phoebe Buffay:</strong> I&#39;m fine, thanks.</p><blockquote><p>我很好，谢谢。</p></blockquote><p><strong>Chandler Bing:</strong> (To Monica) Yeah, see, I can&#39;t pull of baby-doll can I?</p><blockquote><p>（对莫妮卡）是的，看，我拉不动娃娃，是吗？</p></blockquote><p><strong>Monica Geller:</strong> No. I think we learned that from the sugarlips incident. I&#39;m gonna get some tea.</p><blockquote><p>不，我想我们是从sugarlips事件中学到的。我去喝点茶。</p></blockquote><p><strong>Chandler Bing:</strong> Okay.</p><blockquote><p>好的。</p></blockquote><p><em>(Monica leaves and Chandler moves to talk to Phoebe.)</em></p><blockquote><p><em>（莫妮卡离开，钱德勒去和菲比说话。）</em></p></blockquote><p><strong>Chandler Bing:</strong> Hiya doin&#39; pumpkin?</p><blockquote><p>你好，你在做南瓜吗？</p></blockquote><p><strong>Phoebe Buffay:</strong> Nope. (Chandler nods in agreement.)</p><blockquote><p>没有。（钱德勒点头表示同意。）</p></blockquote><p>[Cut to Gary and Monica at the counter.]</p><blockquote><p>[转到柜台的加里和莫妮卡。]</p></blockquote><p><strong>Monica Geller:</strong> So it looks like it&#39;s going really well for you two, huh?</p><blockquote><p>看来你们俩相处得很好，嗯？</p></blockquote><p><strong>Gary:</strong> I know, really well. In fact, I&#39;m gonna ask Phoebe to move in with me.</p><blockquote><p>我知道，真的很好。事实上，我要请菲比搬来和我一起住。</p></blockquote><p><strong>Monica Geller:</strong> (shocked) Oh my God!</p><blockquote><p>（震惊）哦，我的天啊！</p></blockquote><p><strong>Gary:</strong> What do you, what do you think?</p><blockquote><p>你觉得怎么样？</p></blockquote><p><strong>Monica Geller:</strong> I think that is so great! When are you gonna ask her?</p><blockquote><p>我觉得那太棒了！你打算什么时候问她？</p></blockquote><p><strong>Gary:</strong> Tonight, but don&#39;t say anything. Okay?</p><blockquote><p>今晚，但什么也别说。可以</p></blockquote><p><strong>Monica Geller:</strong> I swear, I promise. I promise. Oh my God, I&#39;m so excited! {And I just can&#39;t hide it! I&#39;m about to lose control and I think I like it! Sorry, just couldn&#39;t resist it.} All right, listen let me tell you, do not get her flowers. Okay? Because y&#39;know, she cries when they die, and there&#39;s the whole funeral…</p><blockquote><p>我发誓，我保证。我保证。天哪，我太激动了！{我无法隐藏它！我快要失控了，我想我喜欢它！对不起，我无法抗拒。}好吧，听我说，别给她买花。可以因为你知道，他们死的时候她会哭，整个葬礼都是这样的…</p></blockquote><p><strong>Gary:</strong> (To Phoebe) I&#39;ll see you after work sweetie. (Kisses her.)</p><blockquote><p>（对菲比）下班后见，亲爱的。（吻她。）</p></blockquote><p><strong>Phoebe Buffay:</strong> Okay. Bye!</p><blockquote><p>好的。再见！</p></blockquote><p><em>(Gary exits and Monica rejoins them.)</em></p><blockquote><p><em>（加里退出，莫妮卡重新加入他们。）</em></p></blockquote><p><strong>Phoebe Buffay:</strong> So, what movie should we see?</p><blockquote><p>那么，我们应该看什么电影？</p></blockquote><p><strong>Monica Geller:</strong> (sitting down) Gary&#39;s gonna ask you to move in with him!!</p><blockquote><p>（坐下）加里会让你和他一起住！！</p></blockquote><p><strong>Phoebe Buffay:</strong> What?! Really?!</p><blockquote><p>什么？！真正地</p></blockquote><p><strong>Monica Geller:</strong> He just told me at the counter. He made me promise not to tell, but I couldn&#39;t hold it in any longer!</p><blockquote><p>他刚才在柜台告诉我的。他让我答应不告诉他，但我再也忍不住了！</p></blockquote><p><strong>Phoebe Buffay:</strong> I can&#39;t believe this!</p><blockquote><p>我真不敢相信！</p></blockquote><p><strong>Chandler Bing:</strong> (terrified) Right, because it&#39;s fast. Because, it&#39;s so fast. It&#39;s fast!</p><blockquote><p>（吓坏了）对，因为它很快。因为，它太快了。太快了！</p></blockquote><p><strong>Monica Geller:</strong> Relax! It&#39;s Phoebe! Not you!</p><blockquote><p>放松点！是菲比！不是你！</p></blockquote><p><strong>Chandler Bing:</strong> Oh! Good for you Pheebs, way to go! (Breathes a sigh of relief)</p><blockquote><p>哦！对你们很好，菲比，干得好！（松了一口气）</p></blockquote><p><strong>Phoebe Buffay:</strong> No, but it is fast. Isn&#39;t it?</p><blockquote><p>没有，但是很快。不是吗？</p></blockquote><p><strong>Monica Geller:</strong> Ohhhh!</p><blockquote><p>哦！</p></blockquote><p><strong>Phoebe Buffay:</strong> No, I like him a lot but I don&#39;t think I&#39;m ready for this!</p><blockquote><p>不，我很喜欢他，但我觉得我还没准备好！</p></blockquote><p><strong>Chandler Bing:</strong> So, what are you gonna do?</p><blockquote><p>那么，你打算怎么办？</p></blockquote><p><strong>Phoebe Buffay:</strong> I don&#39;t know. I&#39;ll just handle it—I&#39;ll ask you to talk to him!</p><blockquote><p>我不知道。我会处理的，我会让你和他谈谈！</p></blockquote><p><strong>Chandler Bing:</strong> Me?! Why me?</p><blockquote><p>我？！为什么是我？</p></blockquote><p><strong>Phoebe Buffay:</strong> Because you are so afraid of commitment! You talk to him, make him scared like you! Make him a…man!</p><blockquote><p>因为你太害怕承诺了！你跟他说话，让他像你一样害怕！让他成为一个…男人！</p></blockquote><p><strong>Chandler Bing:</strong> I&#39;ll try, but I&#39;m not sure what good it would do, y&#39;know? Because I&#39;m a lot less afraid of commitment than I used to be.</p><blockquote><p>我会试试的，但我不确定这会有什么好处，你知道吗？因为我不再像以前那样害怕承诺了。</p></blockquote><p><strong>Monica Geller:</strong> That is so sweet! (She kisses him and turns to add some sugar to her tea.)</p><blockquote><p>太好了！（她吻了吻他，转身往茶里加了些糖。）</p></blockquote><p><strong>Chandler Bing:</strong> (To Phoebe, behind Monica&#39;s back) Still terrified, I&#39;ll take care of it. No problem. (When Monica turns back he smiles and kisses her, when she turns away he nods that he&#39;ll do it to Phoebe.)</p><blockquote><p>（背着莫妮卡对菲比说）还是很害怕，我会处理的。没问题。（当莫妮卡转身时，他微笑着吻她，当她转身时，他点头表示他会对菲比这样做。）</p></blockquote><p>Opening Credits</p><blockquote><p>期初学分</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, Joey and Ross are playing catch with a little foam globe.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋家，乔伊和罗斯正在玩一个小泡沫球接球。</em></p></blockquote><p><strong>Joey Tribbiani:</strong> Hey Ross, is uh, is Staten Island really an island?</p><blockquote><p>嘿，罗斯，史坦顿岛真的是个岛吗？</p></blockquote><p><strong>Ross Geller:</strong> Uh-huh, that&#39;s why they call it Staten Island.</p><blockquote><p>嗯，这就是为什么他们叫它斯塔顿岛。</p></blockquote><p><strong>Joey Tribbiani:</strong> Ohhh. I thought it was like Long Island.</p><blockquote><p>哦。我以为它就像长岛。</p></blockquote><p><strong>Ross Geller:</strong> (he catches the ball and pauses, staring at Joey in disbelief) Also an island.</p><blockquote><p>（他接住球停了下来，难以置信地盯着乔伊）还有一个岛。</p></blockquote><p><em>(The game resumes.)</em></p><blockquote><p><em>（比赛继续。）</em></p></blockquote><p><strong>Joey Tribbiani:</strong> Hey, what time is it?</p><blockquote><p>嘿，现在几点了？</p></blockquote><p><strong>Ross Geller:</strong> (looks at his watch) 2:17.</p><blockquote><p>（看了看表）2:17。</p></blockquote><p><strong>Joey Tribbiani:</strong> Wow! You realize that we&#39;ve been throwing this ball, without dropping it, for like an hour?</p><blockquote><p>哇！你知道我们已经扔了这个球一个小时了吗？</p></blockquote><p><strong>Ross Geller:</strong> Are you serious?!</p><blockquote><p>你是认真的吗？！</p></blockquote><p><strong>Joey Tribbiani:</strong> Yeah. I realized it about a half-hour ago but I didn&#39;t want to say anything &#39;cause I didn&#39;t want to jinx it.</p><blockquote><p>是的。我大约半小时前意识到了这一点，但我什么也不想说，因为我不想倒霉。</p></blockquote><p><strong>Ross Geller:</strong> Wow! We are pretty good at this! Hey! We totally forgot about lunch!</p><blockquote><p>哇！我们在这方面很在行！嘿我们完全忘了吃午饭！</p></blockquote><p><strong>Joey Tribbiani:</strong> Oh, I-I, I think that&#39;s the first time I ever missed a meal! (Checks his pants.) Yeah, my pants are a little loose!</p><blockquote><p>哦，我，我想这是我第一次错过一顿饭！（检查他的裤子）是的，我的裤子有点松！</p></blockquote><p><strong>Rachel Green:</strong> (entering) Hey, you guys…</p><blockquote><p>（进来）嘿，你们这些家伙…</p></blockquote><p><strong>Joey Tribbiani:</strong> Hey!</p><blockquote><p>嘿！</p></blockquote><p><strong>Rachel Green:</strong> Is Monica here?</p><blockquote><p>莫妮卡在吗？</p></blockquote><p>Joey and **Ross Geller: **No.</p><blockquote><p>乔伊和<strong>罗斯·盖勒：</strong>不。</p></blockquote><p><strong>Rachel Green:</strong> All right listen umm, I just bought something I&#39;m not sure she&#39;s gonna like it, and it&#39;s gonna seem a little crazy, but this is something that I wanted since I was a little girl.</p><blockquote><p>好吧，听着，嗯，我刚买了一些我不确定她会喜欢的东西，这看起来有点疯狂，但这是我小时候就想要的东西。</p></blockquote><p><strong>Ross Geller:</strong> You bought Shawn Cassidy!</p><blockquote><p>你买了肖恩·卡西迪！</p></blockquote><p><strong>Rachel Green:</strong> Noo! I wish! Okay, you ready?</p><blockquote><p>不！但愿如此！好了，准备好了吗？</p></blockquote><p>Joey and **Ross Geller: **Yeah!</p><blockquote><p>乔伊和<strong>罗斯·盖勒：</strong>是啊！</p></blockquote><p><strong>Rachel Green:</strong> Okay! (She goes and gets her surprise and when she returns with it, Ross stares in shock.) Check it out!</p><blockquote><p>好的！（她去拿她的惊喜，当她拿着它回来时，罗斯震惊地盯着。）看看！</p></blockquote><p><em>(Joey turns and looks at quite possibly one of the ugliest pets that you can possibly buy on the planet. Rachel has bought herself a hairless cat. Yep, a hairless cat! Joey and Ross start to get sick.)</em></p><blockquote><p><em>（乔伊转过身来，看着一只很可能是这个星球上最丑的宠物之一。瑞秋给自己买了一只无毛猫。是的，一只无毛猫！乔伊和罗斯开始生病了。）</em></p></blockquote><p><strong>Ross Geller:</strong> What-what is it?!</p><blockquote><p>什么事？！</p></blockquote><p><strong>Joey Tribbiani:</strong> What the hell is that?!!</p><blockquote><p>那他妈的是什么？！！</p></blockquote><p><strong>Rachel Green:</strong> It&#39;s a, it&#39;s a cat!</p><blockquote><p>它是一只猫，它是一只猫！</p></blockquote><p><strong>Joey Tribbiani:</strong> That, is not a cat! {I have to agree with Joey on this one.}</p><blockquote><p>那不是猫！{在这一点上我必须同意乔伊的意见。}</p></blockquote><p><strong>Rachel Green:</strong> Yes it is!</p><blockquote><p>是的！</p></blockquote><p><strong>Ross Geller:</strong> Why is it inside out?!</p><blockquote><p>为什么是里里外外的？！</p></blockquote><p><strong>Rachel Green:</strong> Excuse me! But this is a purebred, show-quality Sphinx cat!</p><blockquote><p>对不起！但这是一只纯种的、高质量的狮身人面像猫！</p></blockquote><p><strong>Ross Geller:</strong> How much did you pay for that?</p><blockquote><p>你花了多少钱？</p></blockquote><p><strong>Rachel Green:</strong> Well, it was a little extravagant, but I a pretty good deal.</p><blockquote><p>嗯，这有点奢侈，但我觉得很划算。</p></blockquote><p><strong>Ross Geller:</strong> Yeah? How much?</p><blockquote><p>是吗？多少钱？</p></blockquote><p><strong>Rachel Green:</strong> A thousand bucks.</p><blockquote><p>一千美元。</p></blockquote><p><strong>Ross Geller:</strong> ON A CAT??!!!!</p><blockquote><p>在猫身上？？！！！！</p></blockquote><p><strong>Joey Tribbiani:</strong> It&#39;s not a cat!</p><blockquote><p>它不是猫！</p></blockquote><p><strong>Rachel Green:</strong> All right listen ball boys! My grandmother had one of these when I was a little girl and it was the sweetest thing! I mean it was so cute, it would sit in my lap and purr all day long, and I would drag a shoestring on the ground and he would chase it!</p><blockquote><p>好了，听着，球童们！当我还是个小女孩的时候，我的祖母就有一个，这是最甜蜜的事情！我的意思是它太可爱了，它会坐在我的腿上整天咕噜咕噜，我会在地上拖一根鞋带，它会追逐它！</p></blockquote><p><strong>Ross Geller:</strong> Free cats do that too, y&#39;know. {Which reminds me, if I might get a little political here, support your local animal shelter. Pet shops are not the place to buy dogs and cats from, you get a much better deal from the shelter, plus they probably won&#39;t die on you in a week and a half. If you want a leash, go to the pet shop. If you want the dog for that leash, go to the shelter and save it&#39;s life. Now back to regularly scheduled programming.}</p><blockquote><p>你知道，自由猫也这么做。{这提醒了我，如果我在这里有点政治色彩，支持你当地的动物收容所。宠物店不是买狗和猫的地方，你可以从收容所得到更好的待遇，而且它们可能在一周半内不会死在你身上。如果你想要一条狗带，去宠物店。如果你想要狗带，去收容所d拯救它的生命。现在回到定期计划的程序。}</p></blockquote><p><strong>Joey Tribbiani:</strong> It&#39;s not a cat!</p><blockquote><p>它不是猫！</p></blockquote><p><strong>Rachel Green:</strong> Ugh! Look you guys, I&#39;m really excited about this! Okay? I don&#39;t care what you think! I&#39;m gonna go set up a little litter box for Mrs. Whiskerson. (They both glare at her.) Well, what am I gonna call her? Fluffy?!</p><blockquote><p>啊！你们看，我真的很兴奋！可以我不管你怎么想！我要去给威克森太太准备一个小垃圾箱。（他们都瞪着她）那我怎么称呼她？毛茸茸的</p></blockquote><p><em>(Rachel goes into the bathroom as the guys continue throwing the ball.)</em></p><blockquote><p><em>（瑞秋走进浴室，小伙子们继续扔球。）</em></p></blockquote><p><strong>Ross Geller:</strong> (To Joey) Hey, you wanna get something to eat or uh, do you wanna see how long we can throw this ball back and forth? Huh?</p><blockquote><p>（对乔伊）嘿，你想找点吃的吗？或者，你想看看我们能把这个球来回扔多久？嗯？</p></blockquote><p><strong>Joey Tribbiani:</strong> Uhh, the ball thing.</p><blockquote><p>嗯，舞会的事。</p></blockquote><p><strong>Ross Geller:</strong> Yeah?</p><blockquote><p>是吗？</p></blockquote><p><strong>Joey Tribbiani:</strong> Hey Ross, wouldn&#39;t it be great if we could go two straight hours without dropping it?!</p><blockquote><p>嘿，罗斯，如果我们能连续两个小时不摔下来，那不是很棒吗？！</p></blockquote><p><strong>Ross Geller:</strong> Uhh, yeah it would! Let&#39;s do it!</p><blockquote><p>嗯，是的，会的！让我们做吧！</p></blockquote><p><strong>Joey Tribbiani:</strong> Okay!</p><blockquote><p>好的！</p></blockquote><p><em>(They throw the ball back and forth once.)</em></p><blockquote><p><em>（他们来回抛了一次球。）</em></p></blockquote><p><strong>Joey Tribbiani:</strong> (catches the ball) Uh-oh.</p><blockquote><p>（接住球）哦。</p></blockquote><p><strong>Ross Geller:</strong> What?</p><blockquote><p>什么？</p></blockquote><p><strong>Joey Tribbiani:</strong> I have to pee. And Rachel&#39;s in the bathroom!</p><blockquote><p>我得小便。瑞秋在浴室里！</p></blockquote><p>[Cut to Chandler and Joey&#39;s, Ross is seen throwing the ball into the bathroom, presumably where Joey is currently using the facilities.]</p><blockquote><p>[切到钱德勒和乔伊家，看到罗斯把球扔进浴室，大概是乔伊正在使用厕所的地方。]</p></blockquote><p><strong>Joey Tribbiani:</strong> Man, I didn&#39;t think we were gonna make it!</p><blockquote><p>伙计，我没想到我们会成功！</p></blockquote><p><strong>Ross Geller:</strong> I know! (Looks at the ball in his hands.) Don&#39;t switch hands, okay?</p><blockquote><p>我知道！（看着他手中的球）不要换手，好吗？</p></blockquote><hr><p>🎬 <em>the 5th Precinct, Gary&#39;s precinct, Chandler has come to talk to him about commitment. And as he&#39;s walking through the door he notices a couple of &quot;Ladies of the night&quot; sitting there. (If you know what I mean.)</em></p><blockquote><p>🎬 <em>第五选区，加里的选区，钱德勒来和他谈论承诺。当他走进门时，他注意到两个“夜女郎”坐在那里。（如果你知道我的意思。）</em></p></blockquote><p><strong>Chandler Bing:</strong> Hey ladies! What are you in here for? (Laughs at his joke.)</p><blockquote><p>嘿，女士们！你来这里干什么？（笑他的笑话。）</p></blockquote><p><strong>Gary:</strong> Hey Chandler, what are you doing here?</p><blockquote><p>嘿，钱德勒，你在这里干什么？</p></blockquote><p><strong>Chandler Bing:</strong> Gary, I&#39;m here to report a crime.</p><blockquote><p>盖瑞，我是来报案的。</p></blockquote><p><strong>Gary:</strong> Yeah?</p><blockquote><p>是吗？</p></blockquote><p><strong>Chandler Bing:</strong> It is a crime that you and I don&#39;t spend more time together.</p><blockquote><p>你和我没有更多的时间在一起是一种犯罪。</p></blockquote><p><strong>Gary:</strong> (laughs, then suddenly serious) What&#39;s up?</p><blockquote><p>（大笑，然后突然严肃起来）怎么了？</p></blockquote><p><strong>Chandler Bing:</strong> Well, I heard that you thinking about asking Phoebe to move in with you and I thought maybe, we should have a talk. Man to uh, me.</p><blockquote><p>我听说你想让菲比搬来和你住，我想也许我们应该谈谈。男人对我说。</p></blockquote><p><strong>Gary:</strong> Sure. Okay.</p><blockquote><p>当然。可以</p></blockquote><p><strong>Chandler Bing:</strong> Uh, are you crazy? Are you insane? If you live with Phoebe, you two are gonna be y&#39;know, live-living together!</p><blockquote><p>嗯，你疯了吗？你疯了吗？如果你和菲比住在一起，你们两个会住在一起的！</p></blockquote><p><strong>Gary:</strong> Yeah, I-I considered that. I just know it would make me happy.</p><blockquote><p>是的，我考虑过。我只知道这会让我开心。</p></blockquote><p><strong>Chandler Bing:</strong> You mean scared.</p><blockquote><p>你是说害怕。</p></blockquote><p><strong>Gary:</strong> No, I mean happy.</p><blockquote><p>不，我是说快乐。</p></blockquote><p><strong>Chandler Bing:</strong> Scared? Happy?</p><blockquote><p>害怕吗？高兴吗？</p></blockquote><p><strong>Gary:</strong> Chandler, what-what are you doing?</p><blockquote><p>钱德勒，你在干什么？</p></blockquote><p><strong>Chandler Bing:</strong> I am trying to open your eyes, my man! Don&#39;t you see, if you lived with Phoebe she&#39;s always gonna be there. You&#39;re gonna get home, she&#39;s there. You go to bed, she&#39;s there. You wake up and oh yes, she&#39;s there!</p><blockquote><p>我在试着睁开你的眼睛，伙计！你不明白吗，如果你和菲比住在一起，她会一直在那里。你会回家的，她在那里。你去睡觉，她在那儿。你醒来，哦，是的，她在那里！</p></blockquote><p><strong>Gary:</strong> I know! I can&#39;t wait!</p><blockquote><p>我知道！我等不及了！</p></blockquote><p><strong>Chandler Bing:</strong> Were you&#39;re parents happy, or something?</p><blockquote><p>你父母高兴吗？</p></blockquote><p><strong>Gary:</strong> Listen Chandler, the way I see it is that I was lucky enough to find someone that I really love. I just—I wanna be around her as much as I can.</p><blockquote><p>听着，钱德勒，我觉得我很幸运找到了我真正爱的人。我只是想尽我所能和她在一起。</p></blockquote><p><strong>Chandler Bing:</strong> Wow, y&#39;know when you say it, it doesn&#39;t sound so scary.</p><blockquote><p>哇，你知道当你这么说的时候，听起来并没有那么吓人。</p></blockquote><p><strong>Gary:</strong> So you know what I&#39;m talking about, right?</p><blockquote><p>所以你知道我在说什么，对吧？</p></blockquote><p><strong>Chandler Bing:</strong> Yeah, I think I do! Y&#39;know what? You move in with her! You move in with her right now! Maybe I should in with Monica!</p><blockquote><p>是的，我想是的！你知道吗？你和她一起住！你现在就搬来和她住！也许我应该和莫妮卡在一起！</p></blockquote><p><strong>Gary:</strong> No, it&#39;s too soon for you guys.</p><blockquote><p>不，对你们来说太早了。</p></blockquote><p><strong>Chandler Bing:</strong> (pause) Yeah, you&#39;re right about that.</p><blockquote><p>（停顿）是的，你说得对。</p></blockquote><hr><p>🎬 <em>Chandler and Joey&#39;s, Ross and Joey are still playing catch.</em></p><blockquote><p>🎬 <em>钱德勒和乔伊的，罗斯和乔伊还在玩接球。</em></p></blockquote><p><strong>Ross Geller:</strong> …now when they found the remains of the Mesozoic Mastodon they discovered what appeared to be the remains of a Paleozoic Amphibian in its jaws! How did it get there?!</p><blockquote><p>……现在，当他们发现中生代乳齿象的遗骸时，他们在它的颚部发现了似乎是古生代两栖动物的遗骸！它是怎么到那里的？！</p></blockquote><p>{Y&#39;know, sometimes I think the script writers throw in a line like that to try to trip me up. But it won&#39;t work. I&#39;ll always have the last laugh! &lt;manical_laugh.wav&gt; Okay, so maybe I&#39;m a little deluded, it&#39;s probably just my spellchecker. But, I must admit I did get Mesozoic and Paleozoic on the first attempt. Yay me! Anyhoo…}</p><blockquote><p>{你知道，有时候我觉得编剧会用这样的台词来绊倒我。但这行不通。我会一直笑到最后的！&lt;manical_laugh.wav&gt;好吧，也许我有点受骗了，这可能只是我的拼写检查。但是，我必须承认，我第一次尝试时确实遇到了中生代和古生代。耶，我！无论如何…}</p></blockquote><p><strong>Joey Tribbiani:</strong> Maybe this should be more of a quiet game.</p><blockquote><p>也许这应该是一场安静的比赛。</p></blockquote><p>{Oh, all right! Geez, I can&#39;t have any fun!}</p><blockquote><p>{哦，好吧！天哪，我没什么乐趣了！}</p></blockquote><p><strong>Monica Geller:</strong> (entering) Hey guys!</p><blockquote><p>（进来）嘿，伙计们！</p></blockquote><p><strong>Joey Tribbiani:</strong> Hi!</p><blockquote><p>嗨！</p></blockquote><p><strong>Monica Geller:</strong> Joey, I left my watch on the counter last night. (Goes to the counter) It was right here, where is it?</p><blockquote><p>乔伊，我昨晚把手表忘在柜台上了。（走向柜台）就在这里，在哪里？</p></blockquote><p><strong>Joey Tribbiani:</strong> I don&#39;t know.</p><blockquote><p>我不知道。</p></blockquote><p><strong>Monica Geller:</strong> All right, come on, I&#39;m-I&#39;m late for work!</p><blockquote><p>好吧，来吧，我上班迟到了！</p></blockquote><p><strong>Ross Geller:</strong> How do you know? You don&#39;t have a watch.</p><blockquote><p>你怎么知道的？你没有手表。</p></blockquote><p><strong>Monica Geller:</strong> Guys, could you please just stop throwing the ball for one minute and just help me find it!</p><blockquote><p>伙计们，你们能不能别再扔球了，帮我找到它！</p></blockquote><p><strong>Joey Tribbiani:</strong> Oh, I don&#39;t know…. Yeah, can&#39;t do it.</p><blockquote><p>哦，我不知道…。是的，不行。</p></blockquote><p><em>(He throws it back to Ross, but it&#39;s intercepted by Monica and the guys both scream in horror.)</em></p><blockquote><p><em>（他把它扔给罗斯，但被莫妮卡截住了，两人都吓得尖叫。）</em></p></blockquote><p><strong>Monica Geller:</strong> What?!</p><blockquote><p>什么？！</p></blockquote><p><strong>Ross Geller:</strong> Monica, whatever you do, do not drop that ball!</p><blockquote><p>莫妮卡，不管你做什么，都不要把球掉下去！</p></blockquote><p><strong>Joey Tribbiani:</strong> Yeah, we haven&#39;t dropped it in… (Looks to Ross.)</p><blockquote><p>是的，我们没有把它放进去…（看着罗斯。）</p></blockquote><p><strong>Ross Geller:</strong> 2 hours, 27 minutes.</p><blockquote><p>2小时27分钟。</p></blockquote><p><strong>Monica Geller:</strong> Really?!</p><blockquote><p>真的吗？！</p></blockquote><p>⏱ <em>Time lapse, Monica has joined in and is calling to get out of work.</em></p><blockquote><p>⏱ <em>随着时间的推移，莫妮卡加入了进来，并打电话要求停止工作。</em></p></blockquote><p><strong>Monica Geller:</strong> (on phone, faking she&#39;s sick) I-I&#39;m not gonna be able to make it into work today, I don&#39;t feel very good. (Joey makes a high throw and Monica has to catch it way over her head.) (Not sounding sick) Yes!! (Realizes what she just did.) (Sounding sick again) Wow! Uh, for a second there I thought I was really better, but I&#39;m not. (Hangs up and keeps throwing the ball.)</p><blockquote><p>（在电话里假装生病）我——我今天不能上班了，我感觉不太好。（乔伊掷了一个高球，莫妮卡必须从头顶上接住。）（听起来不恶心）是的！！（意识到她刚才做了什么。）（听起来又病了）哇！嗯，有一瞬间我以为我真的好多了，但我没有。（挂断并继续投球。）</p></blockquote><p><em>(Rachel enters.)</em></p><blockquote><p><em>（瑞秋进来了。）</em></p></blockquote><p><strong>Ross Geller:</strong> Hey Rach!</p><blockquote><p>嘿，瑞秋！</p></blockquote><p><strong>Rachel Green:</strong> Hey.</p><blockquote><p>嘿。</p></blockquote><p><strong>Ross Geller:</strong> Check it out! Almost 3 hours without droppin&#39; it!</p><blockquote><p>看看！几乎3个小时没有掉下来！</p></blockquote><p><strong>Rachel Green:</strong> Oh, wow! Congratulations, that&#39;s quite a waste of time.</p><blockquote><p>哦，哇！恭喜你，那真是浪费时间。</p></blockquote><p><strong>Monica Geller:</strong> Rach?</p><blockquote><p>瑞秋？</p></blockquote><p><strong>Rachel Green:</strong> Yeah?</p><blockquote><p>是吗？</p></blockquote><p><strong>Monica Geller:</strong> You have scratches all over you, what happened? (Rachel&#39;s arms are covered with scratches.)</p><blockquote><p>你全身都是抓痕，怎么了？（瑞秋的手臂上满是划痕。）</p></blockquote><p><strong>Rachel Green:</strong> Well, it&#39;s my cat.</p><blockquote><p>嗯，是我的猫。</p></blockquote><p><strong>Monica Geller:</strong> (shocked) What?!</p><blockquote><p>（震惊）什么？！</p></blockquote><p><strong>Rachel Green:</strong> Oh yeah, I got a cat.</p><blockquote><p>哦，是的，我养了一只猫。</p></blockquote><p><strong>Monica Geller:</strong> I don&#39;t want a cat!</p><blockquote><p>我不要猫！</p></blockquote><p><strong>Joey Tribbiani:</strong> Oh, don&#39;t worry, it&#39;s not a cat.</p><blockquote><p>哦，别担心，它不是猫。</p></blockquote><p><strong>Ross Geller:</strong> Yeah.</p><blockquote><p>是的。</p></blockquote><p><strong>Rachel Green:</strong> You guys this cat is nothing like my grandmother&#39;s cat. I mean, it&#39;s not sweet, it&#39;s not cute, I even dragged that little string on the ground, and it just flipped out and scratched the hell out of me. And I swear, I know this sounds crazy, but every time this cat hisses at me I know it&#39;s saying, &quot;Rachel!&quot;</p><blockquote><p>你们这些家伙，这只猫和我祖母的猫一点也不像。我的意思是，它不甜，也不可爱，我甚至把那根小绳子拖到地上，它只是弹了出来，把我抓了个正着。我发誓，我知道这听起来很疯狂，但每次这只猫对我发出嘶嘶声，我就知道它在说，“瑞秋！”</p></blockquote><p><strong>Ross Geller:</strong> Doesn&#39;t sound as crazy as paying a thousand dollars for a cat.</p><blockquote><p>听起来不像花一千美元买一只猫那么疯狂。</p></blockquote><p><strong>Monica Geller:</strong> (To Rachel) What?! You paid a thousand dollars for a cat when you owe me 300!!</p><blockquote><p>（对瑞秋）什么？！你欠我300英镑，却花了1000美元买了一只猫！！</p></blockquote><p><strong>Rachel Green:</strong> Well, I was gonna let you play with it.</p><blockquote><p>我本来想让你玩的。</p></blockquote><hr><p>🎬 <em>Central Perk, Phoebe is drinking coffee as Chandler enters.</em></p><blockquote><p>🎬 <em>中央公园，钱德勒进来时菲比正在喝咖啡。</em></p></blockquote><p><strong>Chandler Bing:</strong> Hi!</p><blockquote><p>嗨！</p></blockquote><p><strong>Phoebe Buffay:</strong> Hmm, did you talk to Gary about the moving in thing?</p><blockquote><p>嗯，你和加里谈过搬家的事吗？</p></blockquote><p><strong>Chandler Bing:</strong> Yes I did, and I think you should do it.</p><blockquote><p>是的，我做了，我想你应该做。</p></blockquote><p><strong>Phoebe Buffay:</strong> What?!</p><blockquote><p>什么？！</p></blockquote><p><strong>Chandler Bing:</strong> He&#39;s a great guy, y&#39;know? And he loves you a lot, you are a very lucky lady.</p><blockquote><p>他是个很棒的人，你知道吗？他非常爱你，你是一个非常幸运的女人。</p></blockquote><p><strong>Phoebe Buffay:</strong> You are useless! Freaking out about commitment is the one thing you can do! The one thing! And you can&#39;t even do that right! God!</p><blockquote><p>你没用！对承诺感到恐惧是你唯一能做的事！只有一件事！而你甚至不能做到这一点！上帝</p></blockquote><p><strong>Chandler Bing:</strong> I’m sorry. (Pause) If you ask me, I&#39;d move in with him.</p><blockquote><p>对不起。（停顿）如果你问我，我会和他一起住。</p></blockquote><p><strong>Phoebe Buffay:</strong> Ohh!! God! (Gary enters and she sees him) Ooh! (To Chandler) Get out of here, good for nothing.</p><blockquote><p>哦！！上帝（加里走了进来，她看到了他）哦！（对钱德勒）离开这里，一无是处。</p></blockquote><p><strong>Gary:</strong> Hey Chandler.</p><blockquote><p>嘿，钱德勒。</p></blockquote><p><strong>Chandler Bing:</strong> Hey Gar!</p><blockquote><p>嘿，盖尔！</p></blockquote><p><strong>Gary:</strong> (To Phoebe) Hi sweetie. (Kisses her.) Hi, can I talk to you for a second?</p><blockquote><p>（对菲比）嗨，亲爱的。（吻了吻她）嗨，我能和你谈谈吗？</p></blockquote><p><strong>Phoebe Buffay:</strong> Yeah! Okay. (They move to the couch.)</p><blockquote><p>是啊！可以（他们移到沙发上。）</p></blockquote><p><strong>Gary:</strong> You look very pretty today.</p><blockquote><p>你今天看起来很漂亮。</p></blockquote><p><strong>Phoebe Buffay:</strong> Thanks! Okay. (They sit down.)</p><blockquote><p>谢谢！可以（他们坐了下来。）</p></blockquote><p><strong>Gary:</strong> Here&#39;s the thing.</p><blockquote><p>事情是这样的。</p></blockquote><p><strong>Phoebe Buffay:</strong> Yeah?</p><blockquote><p>是吗？</p></blockquote><p><strong>Gary:</strong> Y&#39;know I really want to move this relationship forward.</p><blockquote><p>你知道，我真的很想推动这段关系向前发展。</p></blockquote><p><strong>Phoebe Buffay:</strong> Uh-hmm.</p><blockquote><p>嗯。</p></blockquote><p><strong>Gary:</strong> Because if you&#39;re not moving forward, y&#39;know you&#39;re just moving backwards.</p><blockquote><p>因为如果你不前进，你知道你只是在倒退。</p></blockquote><p><strong>Phoebe Buffay:</strong> No that&#39;s not true. If you&#39;re not moving forward, you&#39;re just staying still. And staying still is good. Watch this. (She stays still for a brief second.)</p><blockquote><p>不，那不是真的。如果你不前进，你就只是原地不动。保持静止是很好的。看这个。（她静了一会儿。）</p></blockquote><p><strong>Gary:</strong> Phoebe?</p><blockquote><p>菲比？</p></blockquote><p><strong>Phoebe Buffay:</strong> Yeah?</p><blockquote><p>是吗？</p></blockquote><p><strong>Gary:</strong> I want you to move in with me.</p><blockquote><p>我要你搬来和我一起住。</p></blockquote><p><strong>Phoebe Buffay:</strong> That is so sweet. But don&#39;t you think it&#39;s a little too soon? I mean there&#39;s so much we don&#39;t know about each other.</p><blockquote><p>太好了。但是你不觉得有点太早了吗？我的意思是我们彼此有太多的不了解。</p></blockquote><p><strong>Gary:</strong> (disappointed) Oh. Oh-oh-okay, I get it.</p><blockquote><p>（失望）哦。好吧，我明白了。</p></blockquote><p><strong>Phoebe Buffay:</strong> I just—I don&#39;t want us to jump into something we&#39;re not ready for.</p><blockquote><p>我只是，我不想我们跳进我们还没准备好的事情。</p></blockquote><p><strong>Gary:</strong> (disappointed more) Uh-huh.</p><blockquote><p>（更加失望）嗯。</p></blockquote><p><strong>Phoebe Buffay:</strong> I really don&#39;t want to mess up what we have. I&#39;m just—I&#39;m worried it&#39;s gonna be a big mistake.</p><blockquote><p>我真的不想把我们现有的搞砸。我只是担心这会是个大错误。</p></blockquote><p><strong>Gary:</strong> (on the verge of tears) Yeah.</p><blockquote><p>（快要哭了）是的。</p></blockquote><p><strong>Phoebe Buffay:</strong> Which is why my answer is yes!</p><blockquote><p>这就是为什么我的答案是肯定的！</p></blockquote><p><strong>Gary:</strong> (suddenly happy) Really?!</p><blockquote><p>（突然高兴起来）真的吗？！</p></blockquote><p><strong>Phoebe Buffay:</strong> Uh-huh! (They hug.) I&#39;m so…happy. (She&#39;s not happy.)</p><blockquote><p>嗯哼！（他们拥抱）我太…高兴了。（她不高兴。）</p></blockquote><p>Commercial Break</p><blockquote><p>商业休息</p></blockquote><hr><p>🎬 <em>Chandler and Joey&#39;s, Joey, Ross, and Monica are still playing catch, with Chandler looking on. Joey throws the ball to Monica who catches it and whips it at Ross.</em></p><blockquote><p>🎬 <em>钱德勒和乔伊的，乔伊，罗斯和莫妮卡还在玩接球，钱德勒在一旁看着。乔伊把球扔给莫妮卡，莫妮卡接住了球，然后鞭打罗斯。</em></p></blockquote><p><strong>Ross Geller:</strong> (catching the ball) Monica! Stop throwing it so hard! We&#39;re on the same team!</p><blockquote><p>（接球）莫妮卡！别再使劲扔了！我们是同一队的！</p></blockquote><p><strong>Chandler Bing:</strong> Four hours? You guys have been doing this for four hours?</p><blockquote><p>四个小时？你们已经做了四个小时了？</p></blockquote><p><strong>Joey Tribbiani:</strong> That&#39;s right baby.</p><blockquote><p>没错，宝贝。</p></blockquote><p><strong>Chandler Bing:</strong> All right, let me in. (He jumps off of the counter to join in the game.)</p><blockquote><p>好吧，让我进去。（他跳下柜台加入游戏。）</p></blockquote><p><strong>Monica Geller:</strong> (jumping in front of him) No-no! Don&#39;t do it! Don&#39;t!</p><blockquote><p>（跳到他面前）不，不！别这样！不要！</p></blockquote><p><strong>Chandler Bing:</strong> What?</p><blockquote><p>什么？</p></blockquote><p><strong>Monica Geller:</strong> He&#39;s a dropper!</p><blockquote><p>他是个滴管！</p></blockquote><p><strong>Joey Tribbiani:</strong> Oh yeah, that&#39;s right!</p><blockquote><p>哦，是的，没错！</p></blockquote><p><strong>Chandler Bing:</strong> I&#39;m not a dropper!</p><blockquote><p>我不是滴管！</p></blockquote><p><strong>Ross Geller:</strong> It&#39;s really a uh-uh three person game, y&#39;know?</p><blockquote><p>这真的是一个三人游戏，你知道吗？</p></blockquote><p><strong>Chandler Bing:</strong> It&#39;s throwing and catching!</p><blockquote><p>这是投球和接球！</p></blockquote><p><strong>Ross Geller:</strong> All right. (He gently tosses the ball to Chandler who catches it.)</p><blockquote><p>好的。（他轻轻地把球抛给钱德勒，钱德勒接住了球。）</p></blockquote><p><strong>Chandler Bing:</strong> Oh! Oh! That&#39;s so hard. (Starts to juggle the ball, but loses control and almost drops it and hands it to Monica.)</p><blockquote><p>哦！哦那太难了。（开始玩杂耍，但失去了控制，差点把球掉到地上，递给莫妮卡。）</p></blockquote><p><em>(Rachel enters with the &quot;cat&quot; and the chick and the duck start to get riled up.)</em></p><blockquote><p><em>（瑞秋带着“猫”进来，小鸡和小鸭开始生气。）</em></p></blockquote><p><strong>Joey Tribbiani:</strong> Whoa-whoa you guys, it&#39;s not a cat!</p><blockquote><p>哇哇你们这些家伙，这不是猫！</p></blockquote><p><strong>Monica Geller:</strong> Oh my—Oh good God!</p><blockquote><p>我的天啊！</p></blockquote><p><strong>Rachel Green:</strong> (she&#39;s wearing an oven mitt to protect her hand) I give up you guys, I don&#39;t know what I&#39;m going to do with this thing!</p><blockquote><p>（她戴着烤箱手套保护她的手）我放弃你们了，我不知道我要拿这东西做什么！</p></blockquote><p><strong>Ross Geller:</strong> Baking it didn&#39;t help, huh?</p><blockquote><p>烤也没用，嗯？</p></blockquote><p><strong>Monica Geller:</strong> So, why don&#39;t you just take it back to where you got it?</p><blockquote><p>那么，你为什么不把它带回你拿到的地方呢？</p></blockquote><p><strong>Rachel Green:</strong> I tried! They won&#39;t take her back.</p><blockquote><p>我试过了！他们不会把她带回去的。</p></blockquote><p><strong>Chandler Bing:</strong> Maybe that&#39;s because she&#39;s a minion of the anti-Christ.</p><blockquote><p>也许是因为她是反基督的奴才。</p></blockquote><p><strong>Monica Geller:</strong> Rach, why won&#39;t they take it back?</p><blockquote><p>瑞秋，他们为什么不收回呢？</p></blockquote><p><strong>Rachel Green:</strong> Well, they said would but they would only give me store credit. I mean, what am I going to do, get a thousand regular cats?</p><blockquote><p>嗯，他们说会的，但他们只会给我商店积分。我是说，我该怎么办，养一千只普通猫？</p></blockquote><p><strong>Monica Geller:</strong> Look, if you want you can keep it at our place until you find out what to do with it.</p><blockquote><p>听着，如果你想的话，你可以把它放在我们这里，直到你知道怎么处理它。</p></blockquote><p><strong>Rachel Green:</strong> No Mon that&#39;s not the point. I&#39;m out a thousand dollars, I&#39;m all scratched up, and I&#39;m stuck with this stupid cat that looks like a hand! (Storms out.)</p><blockquote><p>不，妈妈，这不是重点。我身无分文，身无分文，被这只看起来像只手的笨猫困住了！（怒气冲冲地走了出去。）</p></blockquote><p><em>(Monica sneezes.)</em></p><blockquote><p><em>（莫妮卡打了个喷嚏。）</em></p></blockquote><p><strong>Monica Geller:</strong> Oh my God, the cat&#39;s made my eyes water! Don&#39;t-don&#39;t throw it to me! My vision&#39;s been compromised!! (Quickly grabs a tissue to wipe her eyes.) Oh God! Okay. Okay. It&#39;s okay. Man, that was close.</p><blockquote><p>哦，我的天啊，那只猫让我的眼睛流泪了！别，别把它扔给我！我的视力受损了！！（迅速抓起纸巾擦了擦眼睛。）天哪！可以可以没关系。老兄，差一点。</p></blockquote><p><strong>Chandler Bing:</strong> Yeah, you almost overreacted to something.</p><blockquote><p>是啊，你几乎对什么反应过度了。</p></blockquote><p><strong>Phoebe and Gary:</strong> (entering) Hey!</p><blockquote><p>（进来）嘿！</p></blockquote><p><strong>All:</strong> Hey!</p><blockquote><p>嘿！</p></blockquote><p><strong>Gary:</strong> We have great news!</p><blockquote><p>我们有好消息！</p></blockquote><p><strong>Phoebe Buffay:</strong> We&#39;re moving in together! Isn&#39;t it great! Yay!</p><blockquote><p>我们要搬到一起住了！太棒了！耶！</p></blockquote><p><strong>All:</strong> Congratulations! Congrats!</p><blockquote><p>祝贺你！恭喜！</p></blockquote><p><strong>Phoebe Buffay:</strong> I know, I&#39;m so excited!</p><blockquote><p>我知道，我太激动了！</p></blockquote><p><strong>Gary:</strong> So am I!</p><blockquote><p>我也是！</p></blockquote><p><strong>Phoebe Buffay:</strong> Well, you&#39;re not more excited than I am! No way! I&#39;m the most excited!</p><blockquote><p>嗯，你并不比我更兴奋！不可能！我是最兴奋的！</p></blockquote><p><strong>Gary:</strong> Okay, I&#39;ll see you at the station later.</p><blockquote><p>好的，我们待会在车站见。</p></blockquote><p><strong>Phoebe Buffay:</strong> Okay, yeah, I&#39;ll see you later! Don&#39;t forget about the moving in!</p><blockquote><p>好的，好的，回头见！别忘了搬进来的事！</p></blockquote><p><strong>Gary:</strong> All right.</p><blockquote><p>好的。</p></blockquote><p><em>(Phoebe closes the door behind him.)</em></p><blockquote><p><em>（菲比关上了身后的门。）</em></p></blockquote><p><strong>Monica Geller:</strong> So you&#39;re moving in with him. What happened?</p><blockquote><p>那么你要和他一起住了。怎么搞的？</p></blockquote><p><strong>Phoebe Buffay:</strong> I couldn&#39;t tell him no. He got so sad. Maybe it&#39;ll be all right. I do really like him a lot and probably do it eventually anyway and plus, think of all the money I&#39;ll save on stamps.</p><blockquote><p>我不能告诉他不。他太伤心了。也许会没事的。我真的很喜欢他，也许最终还是会这么做，而且，想想我能省下多少钱买邮票。</p></blockquote><p><strong>Monica Geller:</strong> Why, do you write him a lot?</p><blockquote><p>为什么，你经常给他写信吗？</p></blockquote><p><strong>Phoebe Buffay:</strong> No, I just heard when people live together, they split the cost of stamps. Don&#39;t they?</p><blockquote><p>不，我只是听说当人们住在一起时，他们分摊邮票的费用。不是吗？</p></blockquote><p><strong>All:</strong> Yeah! That&#39;s right. Yeah-yeah! Yeah!</p><blockquote><p>是啊！这是正确的。是的，是的！是 啊</p></blockquote><p><em>(Rachel enters with the cat, wearing the oven mitt, and startles Phoebe.)</em></p><blockquote><p><em>（瑞秋带着烤箱手套带着猫进来，吓了菲比一跳。）</em></p></blockquote><p><strong>Phoebe Buffay:</strong> Oh, I&#39;m sorry, the oven mitts really freaked me out.</p><blockquote><p>哦，对不起，烤箱手套把我吓坏了。</p></blockquote><hr><p>🎬 <em>Gary&#39;s precinct, Phoebe is entering.</em></p><blockquote><p>🎬 <em>加里的辖区，菲比正在进入。</em></p></blockquote><p><strong>Gary:</strong> Hey, honey! Okay, so did you find any apartments? Anything in Brooklyn Heights?</p><blockquote><p>嘿，亲爱的！好的，你找到公寓了吗？布鲁克林高地有什么事吗？</p></blockquote><p><strong>Phoebe Buffay:</strong> No, nothing.</p><blockquote><p>没有，没什么。</p></blockquote><p><strong>Gary:</strong> Oh really?</p><blockquote><p>哦，真的吗？</p></blockquote><p><strong>Phoebe Buffay:</strong> Yeah.</p><blockquote><p>是的。</p></blockquote><p><strong>Gary:</strong> Nothing at all?</p><blockquote><p>什么都没有？</p></blockquote><p><strong>Phoebe Buffay:</strong> No, as soon as something opens up we&#39;ll move right in. Unless it doesn&#39;t have a pool, I need a pool. (Turns away from him.)</p><blockquote><p>不，一旦有什么事情发生，我们就马上搬进去。除非它没有游泳池，否则我需要一个游泳池。（转身离开他。）</p></blockquote><p><strong>Gary:</strong> Phoebe, can I talk to you for a second?</p><blockquote><p>菲比，我能和你谈谈吗？</p></blockquote><p><strong>Phoebe Buffay:</strong> Uh-huh!</p><blockquote><p>嗯哼！</p></blockquote><p><em>(He takes her into one of those typical interrogation rooms you see on TV and in the movies. Which is really appropriate here, since this is a TV show. What are the odds of that?)</em></p><blockquote><p><em>（他把她带到一个典型的审讯室，你可以在电视和电影中看到。这在这里是非常合适的，因为这是一个电视节目。这样的可能性有多大？）</em></p></blockquote><p><strong>Gary:</strong> Take a seat. You okay? You feeling all right? (Closes the door and takes off his coat.)</p><blockquote><p>请坐。你没事吧？你感觉还好吗？（关上门，脱下外套。）</p></blockquote><p><strong>Phoebe Buffay:</strong> (sits down) Yeah, I feel great. &#39;Cause we&#39;re moving in together.</p><blockquote><p>（坐下）是的，我感觉很好因为我们要搬到一起。</p></blockquote><p><strong>Gary:</strong> So you uh, you checked the paper for listings in Brooklyn Heights, right? You-you checked the Post?</p><blockquote><p>所以你，呃，你在报纸上查了布鲁克林高地的房源，对吗？你查过邮件了吗？</p></blockquote><p><strong>Phoebe Buffay:</strong> Yeah, uh-huh, there was nothing. (Pause) Can I get some water?</p><blockquote><p>是的，嗯，什么都没有。（停顿）我能喝点水吗？</p></blockquote><p><strong>Gary:</strong> In a minute. You-you checked today&#39;s Post?</p><blockquote><p>马上。你看过今天的帖子了吗？</p></blockquote><p><strong>Phoebe Buffay:</strong> Umm, yeah! Today&#39;s.</p><blockquote><p>嗯，是的！今天的。</p></blockquote><p><strong>Gary:</strong> &#39;Cause uh, this is today&#39;s Post (produces one from the other chair) and uh, these are the listings I found. (Points) Brooklyn Heights, two bedroom. (Points) Brooklyn Heights, one bedroom. (Points) Brooklyn Heights, (points) Brooklyn Heights, (points) Brooklyn Heights!</p><blockquote><p>因为，嗯，这是今天的帖子（从另一张椅子上产生一张），嗯，这些是我找到的列表。布鲁克林高地，两居室。布鲁克林高地，一间卧室。布鲁克林高地，布鲁克林高地，布鲁克林高地，布鲁克林高地！</p></blockquote><p><strong>Phoebe Buffay:</strong> (looks at the paper) Are these for rent! I thought people were just bragging!</p><blockquote><p>（看着报纸）这些是出租的吗！我以为人们只是在吹牛！</p></blockquote><p><strong>Gary:</strong> Let me tell you what I think might be going on. (Phoebe looks down in shame.) No-no-no, don&#39;t look at the table. Look at me. (Points to his eyes and she does so) Okay, I think somebody asked someone to move in with them. And I think someone said, &quot;Yes&quot; but now she&#39;s having doubts because things are moving to fast for someone. Does that sound at all possible to you?</p><blockquote><p>让我告诉你我认为可能发生了什么。（菲比羞愧地低下头）不，不，不要看桌子。看看我。（指着他的眼睛，她照做了）好吧，我想有人让别人搬进来和他们住。我想有人会说“是的”，但现在她有了怀疑，因为对某人来说事情发展得很快。你觉得这可能吗？</p></blockquote><p><strong>Phoebe Buffay:</strong> Yes. Yes! Fine! I am someone! You want me to say it? I have doubts! (Pause) I&#39;m sorry! (Puts her head down.)</p><blockquote><p>是的。对好的我是某人！你要我说吗？我有怀疑！（停顿）对不起！（低下头。）</p></blockquote><p><strong>Gary:</strong> Phoebe…</p><blockquote><p>菲比…</p></blockquote><p><strong>Phoebe Buffay:</strong> Yeah?</p><blockquote><p>是吗？</p></blockquote><p><strong>Gary:</strong> Phoebe, it&#39;s okay that you feel this way. I mean it is soon. And there&#39;s a lot of things we don&#39;t know about each other, and I just figure that everything I really like. And the things I don&#39;t know, I get to learn about at someplace with both our names on the mailbox.</p><blockquote><p>菲比，你这样想没关系。我的意思是很快。还有很多我们彼此不了解的事情，我只是觉得我真正喜欢的一切。还有一些我不知道的事情，我会在邮箱上写着我们两个名字的地方去了解。</p></blockquote><p><strong>Phoebe Buffay:</strong> That&#39;s so sweet.</p><blockquote><p>太好了。</p></blockquote><p><strong>Gary:</strong> Sweethart, but none of that matters if it&#39;s too soon for you. It&#39;s fine! We don&#39;t have to move in together. I just—I want you to be happy</p><blockquote><p>斯威特哈特，但如果你觉得太早的话，这些都不重要。很好！我们不必搬到一起住。我只是想让你开心</p></blockquote><p><strong>Phoebe Buffay:</strong> Living with you would make me happy.</p><blockquote><p>和你住在一起会让我很开心。</p></blockquote><p><strong>Gary:</strong> Phoebe, you don&#39;t have to say that.</p><blockquote><p>菲比，你没必要这么说。</p></blockquote><p><strong>Phoebe Buffay:</strong> No, I really wanna live with you! I wanna move in with you!</p><blockquote><p>不，我真的很想和你住在一起！我想和你一起住！</p></blockquote><p><strong>Gary:</strong> Are you sure?</p><blockquote><p>你确定吗？</p></blockquote><p><strong>Phoebe Buffay:</strong> Yes. Definitely! Yes! Let&#39;s live in an apartment that we both live in! (Hugs him.)</p><blockquote><p>是的。肯定对让我们住在我们都住的公寓里！（拥抱他。）</p></blockquote><p><strong>Gary:</strong> Oh that&#39;s great!</p><blockquote><p>哦，太好了！</p></blockquote><p><strong>Phoebe Buffay:</strong> Oh wait, one sec. One sec. (Goes to the mirror) Hey you! Behind the glass! Who are you looking at! I&#39;ve always wanted to say that when I was in one of these rooms, (sees the look on his face) which was never!</p><blockquote><p>哦，等等，等一下。一秒钟。（走向镜子）嘿，你！在玻璃后面！你在看谁！我一直想说，当我在其中一个房间时，（看到他脸上的表情），这从来都不是！</p></blockquote><hr><p>🎬 <em>The street outside Central Perk, Rachel is trying to sell the cat.</em></p><blockquote><p>🎬 <em>中央公园外的街道上，瑞秋正试图卖掉这只猫。</em></p></blockquote><p><strong>Rachel Green:</strong> Show cat! Quality show cat! Show cat! (A woman approaches.)</p><blockquote><p>给猫看！品质秀猫！给猫看！（一位女士走近。）</p></blockquote><p>Woman No. 1: (looks into the box) Oh my God! What&#39;s wrong with your baby?!</p><blockquote><p>（看着盒子）哦，我的天啊！你的孩子怎么了？！</p></blockquote><p><strong>Rachel Green:</strong> It&#39;s not a baby! It&#39;s a cat!</p><blockquote><p>不是婴儿！它是一只猫！</p></blockquote><p>Woman No. 1: Eew! It&#39;s creepy looking!</p><blockquote><p>哎哟！看起来很恐怖！</p></blockquote><p><strong>Rachel Green:</strong> Oh no! No! It&#39;s actually—it&#39;s very sweet. It&#39;s very sweet. Look! (Goes to pet it and it hisses at her.) Yeah, do you want it?</p><blockquote><p>哦，不！不实际上它很甜。它很甜。看！（抚摸它，它向她发出嘶嘶声）是的，你想要吗？</p></blockquote><p>Woman No. 1: (laughs) No, I hate cats.</p><blockquote><p>（笑）不，我讨厌猫。</p></blockquote><p><strong>Rachel Green:</strong> Well, so then what are you doing to me? Okay? Just get out of here! All right? Move on!</p><blockquote><p>那你对我做了什么？可以快离开这里！好吧继续前进！</p></blockquote><p><em>(Another woman approaches.)</em></p><blockquote><p><em>（另一位女士走近。）</em></p></blockquote><p>Woman No. 2: Wow! What an unusual cat!</p><blockquote><p>哇！多么不寻常的一只猫！</p></blockquote><p><strong>Rachel Green:</strong> Yes! Thank you! Exactly! You want it?</p><blockquote><p>是的！非常感谢。确切地你想要吗？</p></blockquote><p>Woman No. 2: Maybe. I was thinking about getting a cat, I was just going to go to the shelter (Good for her) but… Okay, why not?</p><blockquote><p>也许吧。我想养只猫，我只是想去庇护所（对她有好处），但是……好吧，为什么不呢？</p></blockquote><p><strong>Rachel Green:</strong> Oh, terrific! That&#39;ll be $2,000.</p><blockquote><p>哦，太棒了！总共2000美元。</p></blockquote><p>Woman No. 2: What?!</p><blockquote><p>什么？！</p></blockquote><p><strong>Rachel Green:</strong> Okay, a thousand.</p><blockquote><p>好的，一千。</p></blockquote><p>Woman No. 2: I thought you wanted to adopt your cat.</p><blockquote><p>我以为你想收养你的猫。</p></blockquote><p><strong>Rachel Green:</strong> Well, I do, but you&#39;re just gonna have to actually look at this as more of an investment than a cat.</p><blockquote><p>嗯，我知道，但你得把这看作是一种投资，而不是一只猫。</p></blockquote><p>Woman No. 2: Okay, yeah, I just wanted a cat. (Starts to leave.)</p><blockquote><p>好的，是的，我只是想要一只猫。（开始离开。）</p></blockquote><p><strong>Rachel Green:</strong> (makes some unintelligible sound to stop her from leaving) Obviously you know how to haggle, so I&#39;m not gonna try and take you on. Okay? So $800 and I don&#39;t call the cops because you&#39;re robbing me blind! Blind! (Covers her eyes) Just take cat, leave the money, and run away! Run away! (Uncovers her eyes and sees that the woman has fled) Damnit! (To the cat) Cat, can&#39;t you at least smile or something?! (The cat hisses at her again, it sounds like Rachel) Okay, did anybody just hear that? Anybody?</p><blockquote><p>（发出一些莫名其妙的声音阻止她离开）很明显你知道如何讨价还价，所以我不想和你较量。可以所以800美元，我不报警，因为你在瞎抢我！失明的（捂住眼睛）把猫带走，把钱留下，然后逃走！逃跑（睁开眼睛，看到那个女人逃跑了）该死！（对猫）猫，你难道不能至少微笑一下吗？！（猫再次向她发出嘶嘶声，听起来像瑞秋）好吧，有人听到了吗？任何人</p></blockquote><hr><p>🎬 <em>Chandler and Joey&#39;s, Joey, Ross, Monica, and now Chandler are still playing catch. The guys are exhausted and sitting around the room. Monica is still standing all pumped up and being hyper-competitive yet again. {Okay! We get it! She&#39;s competitive!! Must we see all the time?!}</em></p><blockquote><p>🎬 <em>钱德勒和乔伊的，乔伊，罗斯，莫妮卡，现在钱德勒还在玩接球。男人们都筋疲力尽了，围坐在房间里。莫妮卡仍然站在那里精力充沛，再次充满竞争。{好吧！我们明白了！她很有竞争力！！我们必须一直看到吗？！}</em></p></blockquote><p><strong>Ross Geller:</strong> I&#39;m starving!</p><blockquote><p>我饿死了！</p></blockquote><p><strong>Monica Geller:</strong> Come on guys! Suck it up! We&#39;re closing in on ten hours! It&#39;s gut-check time!</p><blockquote><p>来吧，伙计们！闭嘴！我们快十小时了！是检查肠胃的时候了！</p></blockquote><p><strong>Joey Tribbiani:</strong> I don&#39;t know who made you the boss? All right? We (Ross and him) invented this game!</p><blockquote><p>我不知道是谁让你当老板的？好吧我们（罗斯和他）发明了这个游戏！</p></blockquote><p><strong>Monica Geller:</strong> Please! I made this game what it is.</p><blockquote><p>求你了！我创造了这个游戏。</p></blockquote><p><strong>Chandler Bing:</strong> Not fun anymore?</p><blockquote><p>不再有趣了？</p></blockquote><p><strong>Ross Geller:</strong> I&#39;m still hungry!</p><blockquote><p>我还饿着呢！</p></blockquote><p><strong>Monica Geller:</strong> All right, there&#39;s some pizza at my place, we can all eat with one hand right? Are you with me?</p><blockquote><p>好吧，我家有比萨饼，我们都可以用一只手吃，对吗？你和我在一起吗？</p></blockquote><p><strong>Ross Geller:</strong> I am!</p><blockquote><p>我是！</p></blockquote><p><strong>Monica Geller:</strong> All right! Let&#39;s go! (Runs to the door.) Let&#39;s go Team Monica! (The guys all stop and stare at her) All right, we can work out the name later.</p><blockquote><p>好吧！走吧！（跑向门口）我们走，莫妮卡队！（男人们都停下来盯着她）好吧，我们以后再算出名字。</p></blockquote><p>[Cut to her apartment where Rachel is sitting at the table.]</p><blockquote><p>[切到瑞秋坐在桌旁的公寓。]</p></blockquote><p><strong>Monica Geller:</strong> Rachel! What is your cat doing in one of my bowls!</p><blockquote><p>瑞秋！你的猫在我的碗里干什么！</p></blockquote><p><strong>Rachel Green:</strong> It&#39;s not! I&#39;m defrosting a chicken. (Pause) Oh, I uh sold Mrs. Whiskerson.</p><blockquote><p>不是！我正在解冻一只鸡。（停顿）哦，我把维克森太太卖了。</p></blockquote><p><strong>Ross Geller:</strong> Oh, thank God!</p><blockquote><p>哦，感谢上帝！</p></blockquote><p><strong>Joey Tribbiani:</strong> Did you get your money back?</p><blockquote><p>你拿回钱了吗？</p></blockquote><p><strong>Rachel Green:</strong> Yeah, 15 hundred dollars.</p><blockquote><p>是的，1500美元。</p></blockquote><p><strong>Monica Geller:</strong> Wow! You made a profit!</p><blockquote><p>哇！你赚了钱！</p></blockquote><p><strong>Gunther:</strong> (entering with the cat) I just came for the red-velvet pillow.</p><blockquote><p>（带着猫进来）我只是来拿红色天鹅绒枕头的。</p></blockquote><p><strong>Rachel Green:</strong> Oh yeah, there you go. (Hands over the pillow.)</p><blockquote><p>哦，是的，给你。（把手放在枕头上。）</p></blockquote><p><strong>Gunther:</strong> Thanks Rachel. And-and don&#39;t forget you-you can come visit her anytime you want.</p><blockquote><p>谢谢你，瑞秋。别忘了你可以随时来看她。</p></blockquote><p><strong>Rachel Green:</strong> Oh good, great! I&#39;ll-I&#39;ll keep that in mind. (Turns and walks away.)</p><blockquote><p>哦，太好了，太好了！我会记住的。（转身走开。）</p></blockquote><p><strong>Gunther:</strong> (To Ross) Hey! So what is this? Some kind of snake or something?</p><blockquote><p>（对罗斯）嘿！这是什么？什么蛇什么的？</p></blockquote><hr><p>🎬 <em>Gary and Phoebe&#39;s apartment, it&#39;s morning and they&#39;re both waking up in bed.</em></p><blockquote><p>🎬 <em>加里和菲比的公寓，现在是早上，他们都在床上醒来。</em></p></blockquote><p><strong>Gary:</strong> I really like waking up with you.</p><blockquote><p>我真的很喜欢和你一起醒来。</p></blockquote><p><strong>Phoebe Buffay:</strong> I like waking up with you too. (Looks out the window) Oh! It&#39;s such a beautiful morning. (Some birds are singing outside the window) Oh, I can stay here all day.</p><blockquote><p>我也喜欢和你一起醒来。（看着窗外）哦！这是一个如此美丽的早晨。（一些鸟在窗外唱歌）哦，我可以在这里呆一整天。</p></blockquote><p><strong>Gary:</strong> That would be great!</p><blockquote><p>那太好了！</p></blockquote><p><strong>Phoebe Buffay:</strong> We could have breakfast in bed…</p><blockquote><p>我们可以在床上吃早餐…</p></blockquote><p><strong>Gary:</strong> Wait, just a second.</p><blockquote><p>等等，等一下。</p></blockquote><p><strong>Phoebe Buffay:</strong> Okay. (He grabs his gun and shoots the bird.) Oh! Oh no.</p><blockquote><p>好的。（他抓起枪向鸟开枪。）哦！哦，不。</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, Hyper-competitive Monica, Rachel, Chandler, Joey, and Ross are still playing catch. Monica is finally tiring while the rest of them are totally exhausted and virtually asleep.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋、竞争激烈的莫妮卡、瑞秋、钱德勒、乔伊和罗斯还在玩接球游戏。莫妮卡终于累了，而其余的人都筋疲力尽，几乎睡着了。</em></p></blockquote><p><strong>Monica Geller:</strong> All right! Come on Monica! Look alive! Come on, look alive!</p><blockquote><p>好吧！快点，莫妮卡！活蹦乱跳！来吧，活蹦乱跳！</p></blockquote><p><strong>Phoebe Buffay:</strong> (entering) Oh good, you&#39;re all up.</p><blockquote><p>（进来）哦，很好，你都起来了。</p></blockquote><p><strong>Rachel Green:</strong> Phoebe! It&#39;s 6 o&#39;clock in the morning! Why aren&#39;t you at Gary&#39;s?</p><blockquote><p>菲比！现在是早上6点！你为什么不在加里家？</p></blockquote><p><strong>Phoebe Buffay:</strong> Oh yeah, that&#39;s over.</p><blockquote><p>哦，是的，结束了。</p></blockquote><p><strong>All:</strong> What?!</p><blockquote><p>什么？！</p></blockquote><p><strong>Chandler Bing:</strong> Come on! Gary&#39;s such a great guy! Whatever the problem is, you can work it out!</p><blockquote><p>来吧！加里是个很棒的人！不管问题是什么，你都能解决！</p></blockquote><p><strong>Phoebe Buffay:</strong> He shot a bird!</p><blockquote><p>他射杀了一只鸟！</p></blockquote><p><strong>Chandler Bing:</strong> Oh that is over!</p><blockquote><p>哦，结束了！</p></blockquote><p><strong>All:</strong> That&#39;s terrible! I&#39;m sorry!</p><blockquote><p>太可怕了！我很抱歉！</p></blockquote><p><strong>Rachel Green:</strong> Phoebe, are you okay?</p><blockquote><p>菲比，你没事吧？</p></blockquote><p><strong>Phoebe Buffay:</strong> Yeah. Yeah, I&#39;ll be alright.</p><blockquote><p>是的。是的，我会没事的。</p></blockquote><p><strong>Joey Tribbiani:</strong> Oh hey, here Pheebs. (He throws her the ball.)</p><blockquote><p>哦，嘿，菲比。（他把球扔给了她。）</p></blockquote><p><strong>Phoebe Buffay:</strong> (catches it) Nah, I don&#39;t feel like playing. (She sets the ball down on the table and everyone gasps.)</p><blockquote><p>（接住）不，我不想玩。（她把球放在桌上，每个人都喘着粗气。）</p></blockquote><p><strong>Monica Geller:</strong> It&#39;s okay. It&#39;s okay. Just pretend that it didn&#39;t happen! Okay? No one needs to know! I mean, Phoebe&#39;s not an official ballplayer! I mean, only official ballplayers can drop the ball!</p><blockquote><p>没关系。没关系。只要假装它没有发生！可以没人需要知道！我是说，菲比不是正式的棒球运动员！我的意思是，只有官方的棒球运动员才能丢球！</p></blockquote><p><strong>All:</strong> All right. Okay. I&#39;m starving! (They all get up, thus officially ending the game.)</p><blockquote><p>好的。可以我饿死了！（他们都站了起来，正式结束了比赛。）</p></blockquote><p><strong>Rachel Green:</strong> Phoebe, honey, wanna get some breakfast?</p><blockquote><p>菲比，亲爱的，想吃早餐吗？</p></blockquote><p><strong>Phoebe Buffay:</strong> Yeah!</p><blockquote><p>是啊！</p></blockquote><p><strong>Monica Geller:</strong> Okay! Okay, let&#39;s race! First one there wins! Ha-ha! (Runs out the door and everyone watches her leave.)</p><blockquote><p>好的！好的，我们比赛吧！第一个赢了！哈哈！（跑出门外，每个人都看着她离开。）</p></blockquote><p><em>(Pause)</em></p><blockquote><p><em>（停顿）</em></p></blockquote><p><strong>Chandler Bing:</strong> You guys wanna eat here?</p><blockquote><p>你们想在这里吃饭吗？</p></blockquote><p><strong>All:</strong> Yeah! As long as we&#39;re here!</p><blockquote><p>是啊！只要我们还在这里！</p></blockquote><p>Ending Credits</p><blockquote><p>期末学分</p></blockquote><hr><p>🎬 <em>Central Perk, everyone is there.</em></p><blockquote><p>🎬 <em>中央公园，所有人都在那里</em></p></blockquote><p><strong>Joey Tribbiani:</strong> Man that was great! Huh? Can you believe how long we threw that ball around?</p><blockquote><p>真是太棒了！嗯？你能相信我们把球扔了多久吗？</p></blockquote><p><strong>Rachel Green:</strong> Yeah, it is amazing it lasted that long.</p><blockquote><p>是啊，太神奇了，它持续了那么长时间。</p></blockquote><p><strong>Ross Geller:</strong> I know. My arm is killing me.</p><blockquote><p>我知道。我的胳膊疼死了。</p></blockquote><p><strong>Rachel Green:</strong> No, I meant with the dropper over here. (Points at Chandler.)</p><blockquote><p>不，我是说这里的滴管。（指着钱德勒。）</p></blockquote><p><strong>Chandler Bing:</strong> Y&#39;know, how did I get this reputation as a dropper? Okay? I&#39;m anything but a dropper. (We see various scenes of him dropping a football, a mug of coffee, the phone, an apple, a Frisbee, a record, and the final scene has a ball bouncing off of his chest. I&#39;m not going to describe them, you&#39;ll have to see them.)</p><blockquote><p>你知道，我是怎么得到滴管的名声的？可以我决不是一个滴管。（我们看到他扔掉一个足球、一杯咖啡、电话、一个苹果、一个飞盘、一张唱片的各种场景，最后一个场景是一个球从他的胸口弹起。我不打算描述这些场景，你必须看到它们。）</p></blockquote><p>contrl08.gif (14783 bytes)</p><blockquote><p>contrl08.gif（14783字节）</p></blockquote>`,718)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};